// Varianta WHILE:
int i = 1;
while (i <= 5) {
    cout << i << " ";
    i++;
}

// Varianta FOR (echivalenta):
for (int i = 1; i <= 5; i++) {
    cout << i << " ";
}

// Ambele afiseaza: 1 2 3 4 5

#include <iostream>
using namespace std;

int main() {
    cout << "Numaratoare inversa: ";
    for (int i = 10; i >= 1; i--) {
        cout << i << " ";
    }
    cout << "Lansare!" << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    cout << "Numere pare de la 2 la 20: ";
    for (int i = 2; i <= 20; i += 2) {
        cout << i << " ";
    }
    cout << endl;

    cout << "Puterile lui 2: ";
    for (int p = 1; p <= 1024; p *= 2) {
        cout << p << " ";
    }
    cout << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int n;
    cout << "Introdu n: ";
    cin >> n;

    int suma = 0;
    int produs = 1;

    for (int i = 1; i <= n; i++) {
        suma += i;      // suma = suma + i
        produs *= i;    // produs = produs * i
    }

    cout << "Suma 1+2+...+" << n << " = " << suma << endl;
    cout << n << "! = " << produs << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    for (int i = 1; i <= 10; i++) {
        for (int j = 1; j <= 10; j++) {
            cout << i * j << "\t";
        }
        cout << endl;
    }
    return 0;
}
